ALTER TABLE public.plans ADD COLUMN photos text[] NOT NULL DEFAULT '{}', ADD COLUMN area_lat double precision, ADD COLUMN area_lng double precision, ADD COLUMN what_to_bring text NOT NULL DEFAULT '', ADD COLUMN duration_minutes integer NOT NULL DEFAULT 120, ADD COLUMN host_intro text NOT NULL DEFAULT '', ADD COLUMN early_booking boolean NOT NULL DEFAULT false;
ALTER TABLE public.user_settings ADD COLUMN doodle_background boolean NOT NULL DEFAULT true, ADD COLUMN hang_frequency text NOT NULL DEFAULT 'monthly' CHECK(hang_frequency IN('never','monthly','every_2_months'));
CREATE FUNCTION public.limit_free_alerts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.user_id::text)); IF NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=NEW.user_id AND demo_plus) AND (SELECT count(*) FROM public.saved_alerts WHERE user_id=NEW.user_id)>=2 THEN RAISE EXCEPTION 'Free includes 2 saved alerts. Switch to Tagalong Plus for unlimited alerts.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER limit_free_alerts BEFORE INSERT ON public.saved_alerts FOR EACH ROW EXECUTE FUNCTION public.limit_free_alerts();
CREATE FUNCTION public.gate_host_tools() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT NEW.is_example AND (NEW.recurring_weekly OR NEW.auto_approve OR NEW.capacity>8 OR NEW.early_booking) AND (TG_OP='INSERT' OR NEW.recurring_weekly IS DISTINCT FROM OLD.recurring_weekly OR NEW.auto_approve IS DISTINCT FROM OLD.auto_approve OR NEW.capacity IS DISTINCT FROM OLD.capacity OR NEW.early_booking IS DISTINCT FROM OLD.early_booking) AND NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=NEW.host_id AND demo_plus) THEN RAISE EXCEPTION 'Tagalong Plus is required for advanced host tools'; END IF; RETURN NEW; END $$;
CREATE TRIGGER gate_host_tools BEFORE INSERT OR UPDATE ON public.plans FOR EACH ROW EXECUTE FUNCTION public.gate_host_tools();